{"command": "for d in Nemotron-SFT-Safety-v2 Nemotron-SFT-CUDA-v1 Nemotron-SFT-Competitive-Programming-v2 Nemotron-SFT-Math-v4 Nemotron-SFT-Math-v3 Nemotron-Math-Proofs-v2 Nemotron-SFT-Science-v2 Nemotron-SFT-SWE-v3 Nemotron-SFT-OpenCode-v1 Nemotron-SFT-Agentic-v2 Nemotron-SFT-Multilingual-v2 Nemotron-SFT-Instruction-Following-Chat-v3 Nemotron-Cascade-2-SFT-Data; do echo "=== $d ==="; curl -s "https://datasets-server.huggingface.co/size?dataset=nvidia/$d" | python3 -c "
import json,sys
try:
  d=json.load(sys.stdin)
  s=d.get('size',{})
  for cfg in s.get('configs',[]):
    print(' cfg:',cfg.get('config'),'rows:',cfg.get('num_rows'),'| split:',cfg.get('split'))
except Exception as e:
  print(' error')
"; done", "timeout": 120}

{"command": "for d in Nemotron-SFT-Safety-v2 Nemotron-SFT-Competitive-Programming-v2 Nemotron-SFT-Math-v4 Nemotron-SFT-Math-v3 Nemotron-SFT-OpenCode-v1 Nemotron-SFT-Agentic-v2; do echo "=== $d ==="; curl -s "https://datasets-server.huggingface.co/splits?dataset=nvidia/$d" | python3 -c "
import json,sys
try:
  d=json.load(sys.stdin)
  for s in d.get('splits',[]):
    print(' ',s.get('config'),'/',s.get('split'))
except Exception:
  print(' error')
" | head -25; done", "timeout": 120}

{"command": "echo "=== CP-v1 size ==="; curl -s "https://datasets-server.huggingface.co/size?dataset=nvidia/Nemotron-Competitive-Programming-v1" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for c in d.get('size',{}).get('configs',[]): print(' ',c.get('config'),c.get('num_rows'))
" 2>/dev/null | head; echo "=== nvidia search terminal ==="; curl -s "https://huggingface.co/api/datasets?author=nvidia&search=terminal&limit=20" | python3 -c "import json,sys; [print(d['id'],d.get('lastModified','')[:10]) for d in json.load(sys.stdin)]"; echo "=== nvidia search RTL / long-context ==="; curl -s "https://huggingface.co/api/datasets?author=nvidia&search=RTL&limit=20" | python3 -c "import json,sys; [print(d['id'],d.get('lastModified','')[:10]) for d in json.load(sys.stdin)]"; curl -s "https://huggingface.co/api/datasets?author=nvidia&search=long-context&limit=20" | python3 -c "import json,sys; [print(d['id'],d.get('lastModified','')[:10]) for d in json.load(sys.stdin)]"; echo "=== RL guide stage headers ==="; grep -n "^#\|^##" /tmp/nemo_rl_ultra.md | head -40"}

{"command": "for d in Nemotron-Terminal-Synthetic-Tasks Nemotron-Terminal-Corpus; do echo "=== $d ==="; curl -s "https://huggingface.co/datasets/nvidia/$d/raw/main/README.md" | sed -n '/Dataset Description/,/Dataset Owner/p' | head -25; curl -s "https://datasets-server.huggingface.co/size?dataset=nvidia/$d" | python3 -c "
import json,sys
try:
  d=json.load(sys.stdin)
  print(' rows:', d.get('size',{}).get('dataset',{}).get('num_rows'))
except Exception: print(' size n/a')
"; done"}
